[CmdletBinding()]
param(
    [string]$RepositoryRoot = (Split-Path $PSScriptRoot -Parent),
    [switch]$Update,
    [string]$OutputPath = ''
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$RepositoryRoot = [IO.Path]::GetFullPath($RepositoryRoot)
$referencePath = Join-Path $RepositoryRoot 'docs/generated/source-reference.md'
$lines = [Collections.Generic.List[string]]::new()
$lines.AddRange([string[]]@(
    '# Source declaration reference', '',
    '<!-- Generated by scripts/Sync-SharpProofDocumentation.ps1. Do not edit. -->', '',
    'These are literal source declarations, not evaluated MSBuild defaults or a promise of supported behavior.',
    'Conditions and expressions are preserved. See the authored guides for interpretation.', ''))

function Add-Source([string]$RelativePath, [string]$Content, [string]$Language) {
    $lines.Add("## $RelativePath")
    $lines.Add('')
    $lines.Add("[Source](../../$RelativePath)")
    $lines.Add('')
    $lines.Add('```' + $Language)
    $lines.Add($Content.TrimEnd().Replace("`r`n", "`n"))
    $lines.Add('```')
    $lines.Add('')
}

# Discover public package property declarations rather than maintaining a name list.
foreach ($directory in @('SharpProof.Package/buildTransitive', 'SharpProof.Verifier/buildTransitive')) {
    foreach ($file in Get-ChildItem (Join-Path $RepositoryRoot $directory) -File | Sort-Object Name) {
        if ($file.Extension -notin @('.props', '.targets')) { continue }
        [xml]$document = [IO.File]::ReadAllText($file.FullName)
        $nodes = @($document.SelectNodes('//*[starts-with(local-name(), "SharpProof") and parent::PropertyGroup] | //CompilerVisibleProperty[starts-with(@Include, "SharpProof")]'))
        if ($nodes.Count -gt 0) {
            Add-Source "$directory/$($file.Name)" (($nodes | ForEach-Object { $_.OuterXml }) -join "`n") 'xml'
        }
    }
}

# Public attribute enums are small; retaining the complete declaration also keeps
# XML documentation, bit values, aliases and newly added enum files visible.
foreach ($file in Get-ChildItem (Join-Path $RepositoryRoot 'SharpProof.Attributes') -Filter '*.cs' -File | Sort-Object Name) {
    $content = [IO.File]::ReadAllText($file.FullName)
    if ($content -match '\bpublic\s+enum\s+') {
        Add-Source "SharpProof.Attributes/$($file.Name)" $content 'text'
    }
}
Add-Source 'SharpProof.Release.props' ([IO.File]::ReadAllText((Join-Path $RepositoryRoot 'SharpProof.Release.props'))) 'xml'
$containerScript = [IO.File]::ReadAllText((Join-Path $RepositoryRoot 'scripts/Invoke-SharpProofContainer.ps1'))
$commandSet = [regex]::Match($containerScript, '(?s)\[ValidateSet\((.*?)\)\]\s*\[string\]\$Command')
if (-not $commandSet.Success) { throw 'Cannot locate the canonical tooling command declaration.' }
Add-Source 'scripts/Invoke-SharpProofContainer.ps1' ($commandSet.Value) 'powershell'
$gateSource = [IO.File]::ReadAllText((Join-Path $RepositoryRoot 'SharpProof.Gates/Program.cs'))
$usage = [regex]::Match($gateSource, '(?s)Console\.Error\.WriteLine\("Usage:.*?;')
if (-not $usage.Success) { throw 'Cannot locate the corpus CLI usage declaration.' }
Add-Source 'SharpProof.Gates/Program.cs' $usage.Value 'text'
$expected = ($lines -join "`n") + "`n"
if ($OutputPath) {
    [IO.Directory]::CreateDirectory((Split-Path $OutputPath -Parent)) | Out-Null
    [IO.File]::WriteAllText($OutputPath, $expected, [Text.UTF8Encoding]::new($false))
}
if ($Update) {
    [IO.Directory]::CreateDirectory((Split-Path $referencePath -Parent)) | Out-Null
    [IO.File]::WriteAllText($referencePath, $expected, [Text.UTF8Encoding]::new($false))
}
elseif (-not (Test-Path -LiteralPath $referencePath) -or [IO.File]::ReadAllText($referencePath).Replace("`r`n", "`n") -cne $expected) {
    throw 'Generated documentation is stale. Run docker compose run --rm tooling docs-update and copy artifacts/docs/source-reference.md to docs/generated/source-reference.md.'
}
Write-Host 'Source declaration reference is current.'
